int restore_fpu_checking(struct task_struct *tsk)
{
    int result;

    if (boot_cpu_has(X86_FEATURE_FPU)) {
        /* Clear x87 state with defined values */
        __asm__ __volatile__(
            "fninit\n"
            "fldz\n"
            "fld1\n"
            "fldpi\n"
            "fldl2e\n"
            "fldl2t\n"
            "fstsw %0"
            : "=m"(tsk->fpu_state.x87.swd)
            :
            : "memory");
    }

    result = perform_fpu_restore_check(tsk);
    return result;
}

